// Package broken — невалидный исходник: конфликт встраивания. Каталог в
// testdata игнорируется go-тулом, поэтому пакет не ломает сборку; loader
// загружает его явно и обязан сообщить об ошибке типов, а не упасть.
// (Конфликт одноимённых методов с разными сигнатурами в Go не компилируется
// в принципе — «ошибка генерации с указанием обоих источников» из §3.4
// недостижима для валидных источников, конфликт отлавливается здесь.)
package broken

import "context"

type One interface {
	Get() string
}

type Two interface {
	Get(ctx context.Context) error
}

type Conflict interface {
	One
	Two
}
